<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="theme-color" content="#BB2528"><title>Menú | Mekatos</title>
<link rel="stylesheet" href="{{ asset('css/app.css') }}"><link rel="stylesheet" href="{{ asset('css/mekatos-client.css') }}">
<style>
.client-tools{position:sticky;top:66px;z-index:40;padding:10px 0 12px;background:#f7f7f5}.client-tools-inner{display:flex;gap:10px}.menu-search{flex:1;min-height:44px;padding:10px 13px;border:1px solid #d8d8d5;border-radius:10px;background:#fff}.category-nav{display:flex;gap:7px;overflow:auto;padding:8px 0}.category-nav a{flex:0 0 auto;padding:8px 11px;border:1px solid #dededb;border-radius:999px;background:#fff;text-decoration:none;font-size:.78rem;font-weight:750;color:#555}.category-nav a.active{background:#171717;color:#fff}.search-empty{text-align:center;padding:45px 20px}.product-card[hidden],.menu-section[hidden]{display:none}.product-card.is-in-cart{border-color:#aaa}.product-category-mark{display:inline-flex;width:30px;height:30px;align-items:center;justify-content:center;margin-bottom:8px;border-radius:9px;background:#f0f0ee}.cart-item{display:flex;flex-direction:column;gap:8px;padding:13px 0;border-bottom:1px solid #eee}.cart-item-main{display:flex;justify-content:space-between;gap:12px}.cart-item-main span,.confirm-line-note{display:block;color:#777;font-size:.74rem;margin-top:3px}.cart-item .qty{align-self:flex-end}.item-note textarea{width:100%;min-height:52px;resize:vertical;padding:7px 8px;border:1px solid #d8d8d5;border-radius:8px;background:#fff;font:inherit;font-size:.75rem}.cart-note-preview{display:block;color:#555;background:#f7f7f5;padding:7px 8px;border-radius:7px;font-size:.72rem}.cart-note-preview:before{content:'Detalle: ';font-weight:750}.option-modal-card{width:min(92vw,440px);max-height:90vh;overflow:auto;background:#fff;border-radius:16px;padding:22px;box-shadow:0 20px 70px rgba(0,0,0,.25)}.option-modal-card h2{margin:0 0 6px}.option-modal-card>p{margin:0 0 18px;color:#777}.option-field{margin-bottom:15px}.option-field>span{display:block;margin-bottom:7px;font-size:.78rem;font-weight:800}.option-field select,.option-field input{width:100%;min-height:44px;padding:10px 11px;border:1px solid #d4d4d1;border-radius:9px;background:#fff;font:inherit}.option-actions{display:grid;grid-template-columns:1fr 1.2fr;gap:9px;margin-top:20px}.client-feedback{z-index:120}.client-confirm-card{max-height:min(90vh,720px);overflow:auto}.confirm-actions{position:sticky;bottom:0;padding-top:12px;background:#fff}.client-footer{text-align:center;color:#888;font-size:.78rem;padding:0 0 25px}@media(max-width:760px){.client-tools{top:59px}.client-shell{width:min(100% - 20px,1240px)}.cart-panel{padding:18px}.client-header{padding-inline:12px}}@media(max-width:430px){.option-actions,.confirm-actions{grid-template-columns:1fr}}
</style>
</head>
<body class="client-page">
<header class="client-header"><div><strong>Mekatos</strong><span id="table-label">Cargando mesa...</span></div><button class="button button-primary" id="cart-open" type="button">🛒 Carrito (<span id="cart-count">0</span>)</button></header>
<main class="client-shell"><div id="client-error" class="alert alert-error" hidden></div><section class="client-hero"><span class="eyebrow">Menú digital</span><h1>¿Qué quieres pedir?</h1><p>Explora el menú, arma tu pedido y envíalo directamente a cocina.</p></section><div class="client-tools"><div class="client-tools-inner"><input class="menu-search" id="menu-search" type="search" placeholder="Buscar hamburguesa, pollo, jugo..." autocomplete="off"></div><nav class="category-nav" id="category-nav"></nav></div><div id="menu-container" class="menu-container"><p class="loading-state">Cargando menú...</p></div><div id="search-empty" class="search-empty" hidden><h2>No encontramos ese producto</h2><p>Prueba con otro nombre.</p><button class="button" id="clear-search" type="button">Limpiar búsqueda</button></div></main><footer class="client-footer">Mekatos · Gracias por tu pedido</footer>
<div id="cart-drawer" class="cart-drawer" hidden><div class="cart-overlay" id="cart-close"></div><aside class="cart-panel" aria-label="Carrito"><div class="cart-panel-header"><div><span class="eyebrow">Tu selección</span><h2>Tu pedido</h2></div><button class="button button-small" id="cart-close-button" type="button">Cerrar</button></div><div id="cart-items" class="cart-items"></div><div class="cart-panel-footer"><label class="client-notes"><span>Notas para el pedido</span><textarea id="order-notes" rows="3" maxlength="2000" placeholder="Ej. Sin cebolla, recoger en 15 minutos..."></textarea></label><div class="cart-total"><span>Total</span><strong id="cart-total">$0</strong></div><button class="button button-primary" id="submit-order" type="button">Continuar</button></div></aside></div>
<div id="beverage-modal" class="client-confirm" hidden role="dialog" aria-modal="true"><div class="option-modal-card"><h2 id="beverage-title">Selecciona una opción</h2><p>Elige la opción que quieres pedir.</p><div class="option-field"><span>Opción</span><select id="beverage-option"></select></div><div class="option-actions"><button class="button" id="beverage-cancel" type="button">Cancelar</button><button class="button button-primary" id="beverage-confirm" type="button">Agregar</button></div></div></div>
<div id="juice-modal" class="client-confirm" hidden role="dialog" aria-modal="true"><div class="option-modal-card"><h2>Personaliza tu jugo</h2><p>Selecciona preparación y fruta.</p><div class="option-field"><span>Preparación</span><select id="juice-preparation"><option value="AGUA">En agua · $8.500</option><option value="LECHE">En leche · $9.500</option></select></div><div class="option-field"><span>Fruta</span><select id="juice-fruit"></select></div><div class="option-field"><input id="juice-other" maxlength="100" placeholder="Si eliges Otro, escribe la fruta" hidden></div><div class="option-actions"><button class="button" id="juice-cancel" type="button">Cancelar</button><button class="button button-primary" id="juice-confirm" type="button">Agregar jugo</button></div></div></div>
<div id="order-confirm" class="client-confirm" hidden role="dialog" aria-modal="true"><div class="client-confirm-card"><h2>¿Confirmar pedido?</h2><p>Revisa productos, cantidades y detalles.</p><div id="confirm-summary" class="confirm-summary"></div><div class="confirm-actions"><button class="button" id="cancel-confirm" type="button">Seguir revisando</button><button class="button button-primary" id="accept-confirm" type="button">Sí, enviar pedido</button></div></div></div>
<div id="confirmation" class="confirmation" hidden role="dialog" aria-modal="true"><div class="confirmation-card"><div class="confirmation-icon">✓</div><h2>¡Pedido enviado!</h2><p id="confirmation-text">Tu pedido fue recibido correctamente.</p><button class="button button-primary" id="new-order" type="button">Volver al menú</button></div></div><div id="client-feedback" class="client-feedback"></div>
<script>
const TOKEN=@json($token),STORAGE_KEY=`mekatos-cart-${TOKEN}`;const state={table:null,products:[],categories:[],cart:{},itemNotes:{},juiceOptions:{},beverageOptions:{}};const JUICE_FRUITS=@json($juiceFruits ?? \App\Support\JuiceOptions::FRUITS);const money=v=>'$'+Number(v).toLocaleString('es-CO',{maximumFractionDigits:0});const errorBox=document.getElementById('client-error');function esc(v){return String(v??'').replace(/[&<>'\"]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[s]))}function showError(m){errorBox.textContent=m;errorBox.hidden=false}function hideError(){errorBox.hidden=true}function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify({cart:state.cart,itemNotes:state.itemNotes,juiceOptions:state.juiceOptions,beverageOptions:state.beverageOptions,notes:document.getElementById('order-notes').value}))}function restore(){try{const s=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');state.cart=s?.cart||{};state.itemNotes=s?.itemNotes||{};state.juiceOptions=s?.juiceOptions||{};state.beverageOptions=s?.beverageOptions||{};document.getElementById('order-notes').value=s?.notes||''}catch{}}function icon(n){n=n.toLowerCase();if(n.includes('hamburg'))return'🍔';if(n.includes('pollo'))return'🍗';if(n.includes('perro'))return'🌭';if(n.includes('salchip'))return'🍟';if(n.includes('cerveza'))return'🍺';if(n.includes('bebida')||n.includes('jugo')||n.includes('gaseosa'))return'🥤';if(n.includes('carne')||n.includes('parrilla'))return'🥩';return'🍽️'}function juice(p){return p?.name==='Jugo Natural Jarra'}function hasOptions(p){return Array.isArray(p?.beverage_options)&&p.beverage_options.length>0}function get(id){return state.products.find(p=>String(p.id)===String(id))}function key(id,opt=''){return opt?`${id}::${opt}`:String(id)}
function renderNav(cs){document.getElementById('category-nav').innerHTML=cs.map(c=>`<a href="#cat-${c.id}">${esc(c.name)}</a>`).join('')}
function renderMenu(cs){const available=cs.map(c=>({...c,products:(c.products||[]).filter(p=>p.is_available)})).filter(c=>c.products.length);state.categories=available;state.products=available.flatMap(c=>c.products);renderNav(available);document.getElementById('menu-container').innerHTML=available.map(c=>`<section class="menu-section" id="cat-${c.id}"><div class="menu-section-heading"><h2>${esc(c.name)}</h2><span>${c.products.length} productos</span></div><div class="product-grid">${c.products.map(p=>`<article class="product-card" data-name="${esc(p.name).toLowerCase()}"><span class="product-category-mark">${icon(c.name)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description||'')}</p><div class="product-card-footer"><strong>${money(p.price)}</strong><button class="button button-primary" type="button" data-add="${p.id}">${juice(p)?'Personalizar':hasOptions(p)?'Elegir opción':'Agregar'}</button></div></article>`).join('')}</div></section>`).join('');document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.add)));filter()}
function add(id){const p=get(id);if(!p)return;if(juice(p)){openJuice(id);return}if(hasOptions(p)){openBeverage(id);return}const k=key(id);state.cart[k]=(state.cart[k]||0)+1;save();renderCart()}
let pendingBeverage=null;function openBeverage(id){pendingBeverage=id;const p=get(id),s=document.getElementById('beverage-option');s.innerHTML=p.beverage_options.map(o=>`<option value="${esc(o.name)}">${esc(o.name)}</option>`).join('');document.getElementById('beverage-title').textContent=p.name;document.getElementById('beverage-modal').hidden=false;document.body.style.overflow='hidden';s.focus()}function closeBeverage(){document.getElementById('beverage-modal').hidden=true;pendingBeverage=null;document.body.style.overflow=''}function confirmBeverage(){if(pendingBeverage){const o=document.getElementById('beverage-option').value,k=key(pendingBeverage,o);state.cart[k]=(state.cart[k]||0)+1;state.beverageOptions[k]=o;save();renderCart();closeBeverage()}}
let pendingJuice=null;function openJuice(id){pendingJuice=id;const s=document.getElementById('juice-fruit');s.innerHTML=Object.entries(JUICE_FRUITS).map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('');document.getElementById('juice-modal').hidden=false;document.body.style.overflow='hidden'}function closeJuice(){document.getElementById('juice-modal').hidden=true;pendingJuice=null;document.body.style.overflow=''}function confirmJuice(){if(!pendingJuice)return;const prep=document.getElementById('juice-preparation').value,fruit=document.getElementById('juice-fruit').value,other=document.getElementById('juice-other').value.trim();if(fruit==='OTRO'&&!other){showError('Escribe la fruta si eliges Otro.');return}const k=key(pendingJuice);state.cart[k]=(state.cart[k]||0)+1;state.juiceOptions[k]={preparation:prep,fruit,otherFruit:other};save();renderCart();closeJuice()}
document.getElementById('juice-fruit').addEventListener('change',e=>{document.getElementById('juice-other').hidden=e.target.value!=='OTRO'});
function change(k,d){const n=(state.cart[k]||0)+d;if(n<=0){delete state.cart[k];delete state.itemNotes[k];delete state.juiceOptions[k];delete state.beverageOptions[k]}else state.cart[k]=n;save();renderCart()}
function renderCart(){const box=document.getElementById('cart-items'),entries=Object.entries(state.cart);let total=0,count=0;if(!entries.length){box.innerHTML='<div class="empty-state">Tu carrito está vacío.</div>'}else{box.innerHTML=entries.map(([k,q])=>{let id=k,opt=state.beverageOptions[k]||'';if(k.includes('::'))[id,opt]=k.split('::');const p=get(id);if(!p)return'';const j=juice(p),price=j?(state.juiceOptions[k]?.preparation==='LECHE'?9500:8500):Number(p.price),detail=j?`${state.juiceOptions[k]?.preparation==='LECHE'?'En leche':'En agua'} · ${JUICE_FRUITS[state.juiceOptions[k]?.fruit]||state.juiceOptions[k]?.fruit||''}`:opt;const note=state.itemNotes[k]||'';total+=price*q;count+=q;return`<div class="cart-item"><div class="cart-item-main"><div><strong>${q} × ${esc(p.name)}</strong><span>${esc(detail)}</span></div><strong>${money(price*q)}</strong></div><div class="qty"><button type="button" data-k="${esc(k)}" data-d="-1">−</button><span>${q}</span><button type="button" data-k="${esc(k)}" data-d="1">+</button></div><div class="item-note"><textarea maxlength="500" data-note="${esc(k)}" placeholder="Detalle de este producto">${esc(note)}</textarea></div>${note?`<span class="cart-note-preview">${esc(note)}</span>`:''}</div>`}).join('')}document.getElementById('cart-total').textContent=money(total);document.getElementById('cart-count').textContent=count;box.querySelectorAll('[data-k]').forEach(b=>b.addEventListener('click',()=>change(b.dataset.k,Number(b.dataset.d))));box.querySelectorAll('[data-note]').forEach(t=>t.addEventListener('input',()=>{state.itemNotes[t.dataset.note]=t.value.trim();save()}))}
function toggleCart(o){document.getElementById('cart-drawer').hidden=!o;if(o)renderCart();document.body.style.overflow=o?'hidden':''}function filter(){const q=document.getElementById('menu-search').value.trim().toLowerCase();let n=0;document.querySelectorAll('.product-card').forEach(c=>{const v=!q||c.dataset.name.includes(q);c.hidden=!v;if(v)n++});document.querySelectorAll('.menu-section').forEach(s=>s.hidden=!s.querySelector('.product-card:not([hidden])'));document.getElementById('search-empty').hidden=n>0||!q}
function confirmSummary(){const box=document.getElementById('confirm-summary');box.innerHTML=Object.entries(state.cart).map(([k,q])=>{let id=k,opt=state.beverageOptions[k]||'';if(k.includes('::'))[id,opt]=k.split('::');const p=get(id),j=juice(p),detail=j?(state.juiceOptions[k]?.preparation==='LECHE'?'En leche':'En agua')+' · '+(JUICE_FRUITS[state.juiceOptions[k]?.fruit]||''):opt,note=state.itemNotes[k]||'';const price=j?(state.juiceOptions[k]?.preparation==='LECHE'?9500:8500):Number(p.price);return`<div class="confirm-line"><div><strong>${q} × ${esc(p.name)}</strong><span class="confirm-line-note">${esc(detail)}</span>${note?`<span class="confirm-line-note">Detalle: ${esc(note)}</span>`:''}</div><strong>${money(price*q)}</strong></div>`}).join('')}
function payload(){return Object.entries(state.cart).map(([k,q])=>{let id=k,opt=state.beverageOptions[k]||'';if(k.includes('::'))[id,opt]=k.split('::');const i={product_id:Number(id),quantity:Number(q)};const note=state.itemNotes[k]||'';if(note)i.notes=note;if(juice(get(id)))i.juice_options=state.juiceOptions[k]||{};else if(opt)i.beverage_option=opt;return i})}
async function submit(){const b=document.getElementById('accept-confirm');b.disabled=true;try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({token:TOKEN,notes:document.getElementById('order-notes').value.trim(),items:payload()})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'No fue posible enviar el pedido.');localStorage.removeItem(STORAGE_KEY);state.cart={};state.itemNotes={};state.juiceOptions={};state.beverageOptions={};document.getElementById('order-confirm').hidden=true;toggleCart(false);document.getElementById('confirmation-text').textContent=d.message||'Pedido recibido.';document.getElementById('confirmation').hidden=false;document.body.style.overflow='hidden'}catch(e){showError(e.message)}finally{b.disabled=false}}
async function load(){try{const t=await fetch(`/api/table/${encodeURIComponent(TOKEN)}`,{headers:{Accept:'application/json'}});if(!t.ok)throw new Error('No se pudo cargar la mesa.');const td=await t.json();state.table=td;document.getElementById('table-label').textContent=td.table?.name||td.name||`Mesa ${td.number||''}`;const r=await fetch('/api/menu',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('No se pudo cargar el menú.');const d=await r.json();renderMenu(Array.isArray(d)?d:(d.categories||d.data||[]));restore();renderCart()}catch(e){showError(e.message)}}
document.getElementById('cart-open').onclick=()=>toggleCart(true);document.getElementById('cart-close').onclick=()=>toggleCart(false);document.getElementById('cart-close-button').onclick=()=>toggleCart(false);document.getElementById('beverage-cancel').onclick=closeBeverage;document.getElementById('beverage-confirm').onclick=confirmBeverage;document.getElementById('juice-cancel').onclick=closeJuice;document.getElementById('juice-confirm').onclick=confirmJuice;document.getElementById('submit-order').onclick=()=>{if(!Object.keys(state.cart).length){showError('Agrega al menos un producto.');return}confirmSummary();document.getElementById('order-confirm').hidden=false;document.body.style.overflow='hidden'};document.getElementById('cancel-confirm').onclick=()=>{document.getElementById('order-confirm').hidden=true;document.body.style.overflow=''};document.getElementById('accept-confirm').onclick=submit;document.getElementById('new-order').onclick=()=>{document.getElementById('confirmation').hidden=true;document.body.style.overflow='';renderCart()};document.getElementById('menu-search').oninput=filter;document.getElementById('clear-search').onclick=()=>{document.getElementById('menu-search').value='';filter()};load();
</script></body></html>
